import { AxisScale } from '@visx/axis';
import { scaleLinear } from '@visx/scale';
import { extent } from 'd3-array';

import { getDivergentPointIndex } from './get-divergent-point-index.js';
import { ChartLegendOrientation } from '../../../../types/legend.js';
import { RANGE_LEGEND_PADDING, RANGE_SORTING } from '../constants.js';
import { RangeSorting } from '../types/range-legend.internal.js';
import { RangeItem } from '../types/range-legend.js';

export const getLegendScale = (
  orientation: ChartLegendOrientation,
  items: RangeItem[],
  width: number,
  height: number,
  sorting: RangeSorting,
): AxisScale<number> => {
  const allValues = items.flatMap((item) => [item.from, item.to]);
  const containerSize = orientation === 'horizontal' ? width : height;
  const segmentSize = containerSize / items.length;
  const [min = 0, max = 0] = extent(allValues);
  const hasDivergentPoint = getDivergentPointIndex(items) !== -1;

  /* The range of the scale takes into account the segment of the divergent point for the case of the divergent legend.
   * The divergent point is represented as a segment of an equal size to the other segments
   */
  return scaleLinear({
    domain: [min, max],
    range: [
      RANGE_LEGEND_PADDING,
      hasDivergentPoint
        ? containerSize - segmentSize - RANGE_LEGEND_PADDING * 2
        : containerSize - RANGE_LEGEND_PADDING * 2,
    ],
    clamp: true,
    reverse: sorting === RANGE_SORTING.DESC,
  });
};
